import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:uuid/uuid.dart';import '../../../app/providers.dart';import '../data/chat_models.dart';
final messagesProvider=StreamProvider.family<List<MessageModel>,String>((ref,id)=>ref.watch(chatRepositoryProvider).watchMessages(id));
class ChatScreen extends ConsumerStatefulWidget {const ChatScreen({super.key,required this.conversationId});final String conversationId;@override ConsumerState<ChatScreen> createState()=>_ChatScreenState();} class _ChatScreenState extends ConsumerState<ChatScreen>{final _input=TextEditingController();@override void dispose(){_input.dispose();super.dispose();}Future<void> _send()async{final sender=ref.read(authStateProvider).valueOrNull?.uid;if(sender==null||_input.text.trim().isEmpty)return;final text=_input.text.trim();_input.clear();await ref.read(chatRepositoryProvider).send(MessageModel(id:const Uuid().v4(),conversationId:widget.conversationId,senderId:sender,text:text,type:MessageType.text,createdAt:DateTime.now()));} @override Widget build(BuildContext context){final messages=ref.watch(messagesProvider(widget.conversationId));return Scaffold(appBar:AppBar(title:const Text('المحادثة')),body:Column(children:[Expanded(child:messages.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('تعذر تحميل الرسائل: $e')),data:(items)=>ListView.builder(padding:const EdgeInsets.all(12),itemCount:items.length,itemBuilder:(_,i){final m=items[i];return Align(alignment:m.senderId==ref.read(authStateProvider).valueOrNull?.uid?Alignment.centerRight:Alignment.centerLeft,child:GestureDetector(onLongPress:()=>showModalBottomSheet(context:context,builder:(_)=>Wrap(children:['👍','❤️','😂','😢','😠'].map((r)=>ListTile(title:Text(r),onTap:()async{await ref.read(chatRepositoryProvider).toggleReaction(m,ref.read(authStateProvider).valueOrNull!.uid,r);if(context.mounted)Navigator.pop(context);})).toList())),child:Card(child:Padding(padding:const EdgeInsets.all(10),child:Text(m.isDeleted?'تم حذف هذه الرسالة':m.text))))}))),SafeArea(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:_input,onSubmitted:(_)=>_send(),decoration:const InputDecoration(hintText:'اكتب رسالة…'))),IconButton(onPressed:_send,icon:const Icon(Icons.send))]))) ]));}}
